#!/usr/bin/perl
use strict; use warnings;
my $BIN='/workspace/dataset/test15_executable';
sub run { my @a=@_; my $out; my $pid=open(my $fh,'-|'); die unless defined $pid;
  if(!$pid){ open(STDERR,'>','/dev/null'); exec($BIN,@a); exit 127; }
  local $/; $out=<$fh>; close($fh); my $rc=$?>>8; $out='' unless defined $out; return ($out,$rc); }
sub esc { my $s=shift; $s=~s/([^\x20-\x7e])/sprintf("<%02X>",ord($1))/ge; return $s; }
# base cache: for a given s,h,p,pa with q='' f='' -> full output
my %base;
sub getbase { my($s,$h,$p,$pa)=@_; my $k=join("\0",$s,$h,$p,$pa);
  unless(exists $base{$k}){ my($o,$rc)=run($s,$h,$p,$pa,'',''); $base{$k}=[$o,$rc]; }
  return @{$base{$k}}; }
my ($nf,$nt)=(0,0);
sub check { my($s,$h,$p,$pa,$q,$f,$label)=@_;
  my($bo,$brc)=getbase($s,$h,$p,$pa);
  my @bl=split(/\n/,$bo,-1);
  # base lines: 0..7 plus trailing ''
  my $bts = $bl[6]; my $bvalid = $bl[7];
  my $pred = $bl[0]."\n".$bl[1]."\n".$bl[2]."\n".$bl[3]."\n".$q."\n".$f."\n".
             $bts.(length($q)?"?".$q:"").(length($f)?"#".$f:"")."\n".$bvalid."\n";
  my($o,$rc)=run($s,$h,$p,$pa,$q,$f);
  $nt++;
  if($o ne $pred || $rc!=0){ $nf++;
    print "FAIL[$label] s=[".esc($s)."] h=[".esc($h)."] p=[".esc($p)."] pa=[".esc($pa)."] q=[".esc($q)."] f=[".esc($f)."] rc=$rc\n";
    print "  PRED=[".esc($pred)."]\n  GOT =[".esc($o)."]\n";
  }
}
1;
