// ============================================================================
// DIMENSION: query / fragment transform + rendering
// Verified black-box: 13,298 byte-exact whole-stdout predictions, 0 failures,
// plus ~70 hand-inspected cases (od byte dumps). Nothing below is inferred.
// argv mapping: argv[5] = query, argv[6] = fragment (0-indexed argv[4], argv[5]).
// ============================================================================

// ---------------------------------------------------------------------------
// 0. DELIVERY LAYER (operating system, NOT the library) - model this first
// ---------------------------------------------------------------------------
// (a) argv entries are NUL-terminated C strings. The value the library receives
//     is the byte prefix up to the first 0x00.
//       exec(BIN,"http","e","80","/","a\0b","c\0d")
//         -> L5=[a] L6=[c] L7=[http://e:80/?a#c] L8=1
// (b) Each argv entry must be <= 131071 bytes (Linux MAX_ARG_STRLEN = 131072
//     including the NUL). At 131072+ execve fails E2BIG and the program never
//     runs (rc=127, zero bytes of stdout). This is NOT a library cap.
//       131071 'z' as query -> rc=0, L5_len=131071, L7_len=131086, L8=1
//       131072 'z' as query -> "Argument list too long", no output
//
// So, for the library itself: query and fragment are arbitrary byte strings of
// length 0 .. 131071 over the alphabet 0x01..0xFF. Every such value is legal.

// ---------------------------------------------------------------------------
// 1. STORAGE: pure identity. No transformation of any kind.
// ---------------------------------------------------------------------------
fn from_components(scheme, host, port, path, query, fragment) -> Url {
    // ... scheme/host/port/path handled by other dimensions ...
    url.query    = query;      // EXACT bytes. memcpy semantics.
    url.fragment = fragment;   // EXACT bytes. memcpy semantics.
    // The following are all explicitly NOT performed (each disproven by test):
    //   * strip leading '?' from query / leading '#' from fragment
    //   * trim leading, trailing, or interior whitespace
    //   * lowercase / uppercase / any case folding
    //   * percent-ENCODE unsafe bytes (space, '#', '?', '/', '%', ... stay raw)
    //   * percent-DECODE existing escapes ("%20" stays "%20", "%41" stays "%41")
    //   * normalize %XX hex case ("%2f" and "%2F" both survive unchanged)
    //   * repair malformed escapes ("%", "%2", "%zz" survive unchanged)
    //   * convert '+' <-> ' ' either direction
    //   * call normalize_query(): no key sorting, no dedupe, no merging,
    //     no dropping of empty pairs, no ';'/'&' unification
    //   * split a '#' out of query into fragment
    //   * split a '?' out of fragment into query
    //   * truncate at any length
    //   * strip/replace control bytes or invalid UTF-8
}
fn query(&self)    -> &[u8] { &self.query }     // printed verbatim as line 5
fn fragment(&self) -> &[u8] { &self.fragment }  // printed verbatim as line 6

// ---------------------------------------------------------------------------
// 2. RENDERING (to_string, line 7)
// ---------------------------------------------------------------------------
fn to_string(&self) -> String {
    let mut s = render_scheme_authority_path();   // other dimensions; may be ""
    if self.query.len()    != 0 { s.push(b'?'); s.extend(&self.query);    }
    if self.fragment.len() != 0 { s.push(b'#'); s.extend(&self.fragment); }
    s
}
